<?php
use Moves\Services\{CardInvoices,Finance,FinanceContext};
$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$month=is_string($_GET['mes']??null)&&preg_match('/^20\d{2}-(0[1-9]|1[0-2])$/',$_GET['mes'])?$_GET['mes']:date('Y-m');$cards=$cash=[];$invoice=null;$error=null;
try{$finance=new Finance((int)FinanceContext::currentId());$cards=(new CardInvoices((int)FinanceContext::currentId()))->cards();$cash=array_values(array_filter($finance->accounts(),static fn($a)=>$a['type']!=='credit_card'));if($cards!==[]){$card=(int)($_GET['cartao']??$cards[0]['id']);$invoice=(new CardInvoices((int)FinanceContext::currentId()))->invoice($card,$month);}}catch(Throwable $x){error_log('Realizze cards: '.$x->getMessage());$error='A estrutura de cartões ainda precisa da migration 014.';}
$flash=$_SESSION['finance_flash']??null;unset($_SESSION['finance_flash']);
?>
<?php if(is_array($flash)): ?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>" role="status"><?= $e($flash[1]) ?></p><?php endif; ?>
<section class="card finance-workspace"><div class="finance-toolbar"><div><h2>Cartões e faturas</h2><p class="muted">Compras entram na fatura; pagar gera uma única saída na conta escolhida.</p></div><button class="primary" type="button" data-finance-open="card-purchase">+ Nova compra</button></div>
<?php if($error!==null): ?><div class="finance-empty"><h3>Módulo aguardando atualização</h3><p><?= $e($error) ?></p></div><?php elseif($cards===[]): ?><div class="finance-empty"><h3>Nenhum cartão cadastrado</h3><p>Cadastre um cartão de crédito em Bancos e contas, com dia de fechamento e vencimento.</p></div><?php else: ?>
<form method="get" class="finance-filter-bar" data-swap-get><label>Cartão<select name="cartao"><?php foreach($cards as $c): ?><option value="<?= (int)$c['id'] ?>"<?= (int)$c['id']===(int)($_GET['cartao']??$cards[0]['id'])?' selected':'' ?>><?= $e($c['name']) ?></option><?php endforeach; ?></select></label><label>Mês da fatura<input type="month" name="mes" value="<?= $e($month) ?>"></label><button type="submit">Ver fatura</button></form>
<div class="finance-goal-summary"><div class="finance-goal-stat"><span>Fatura em aberto</span><strong><?= $e(Finance::money((int)$invoice['total_cents'])) ?></strong><small>Vence em <?= $e((new DateTimeImmutable($invoice['due_on']))->format('d/m/Y')) ?></small></div><div class="finance-goal-stat"><span>Compras</span><strong><?= count($invoice['rows']) ?></strong><small><?= $e((new DateTimeImmutable($invoice['start']))->format('d/m')) ?> a <?= $e((new DateTimeImmutable($invoice['end']))->format('d/m')) ?></small></div></div>
<?php if($invoice['rows']===[]): ?><div class="finance-empty"><h3>Fatura sem compras abertas</h3><p>As compras futuras e parceladas aparecerão no ciclo correspondente.</p></div><?php else: ?><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th class="num">Valor</th></tr></thead><tbody><?php foreach($invoice['rows'] as $row): ?><tr><td><?= $e((new DateTimeImmutable($row['due_date']))->format('d/m/Y')) ?></td><td><?= $e($row['description']) ?></td><td><?= $e($row['category']??'—') ?></td><td class="num red"><?= $e(Finance::money((int)$row['amount_cents'])) ?></td></tr><?php endforeach; ?></tbody></table></div>
<form method="post" action="/minha-conta/financeiro/cartao-pagar-fatura" data-finance-confirm="Confirmar o pagamento desta fatura?" class="finance-inline-form"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="back" value="faturas"><input type="hidden" name="card_account_id" value="<?= (int)($_GET['cartao']??$cards[0]['id']) ?>"><input type="hidden" name="month" value="<?= $e($month) ?>"><input type="hidden" name="idempotency_key" value="<?= bin2hex(random_bytes(32)) ?>"><label>Conta de pagamento<select name="source_account_id" required><?php foreach($cash as $a): ?><option value="<?= (int)$a['id'] ?>"><?= $e($a['name']) ?></option><?php endforeach; ?></select></label><label>Data<input type="date" name="paid_on" value="<?= date('Y-m-d') ?>"></label><button class="primary"<?= $cash===[]?' disabled':'' ?>>Pagar fatura</button></form><?php endif; ?><?php endif; ?></section>
<dialog class="finance-dialog" id="card-purchase"><form method="post" action="/minha-conta/financeiro/cartao-compra"><header><h2>Nova compra no cartão</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="back" value="faturas"><input type="hidden" name="idempotency_key" value="<?= bin2hex(random_bytes(32)) ?>"><label>Cartão<select name="card_account_id" required><?php foreach($cards as $c): ?><option value="<?= (int)$c['id'] ?>"><?= $e($c['name']) ?></option><?php endforeach; ?></select></label><label>Descrição<input name="description" maxlength="160" required></label><div class="finance-dialog-row"><label>Valor (R$)<input name="amount" inputmode="decimal" required></label><label>Data da compra<input type="date" name="purchased_on" value="<?= date('Y-m-d') ?>" required></label></div><label>Parcelas<input name="installments" type="number" min="1" max="120" value="1" required></label><footer><button type="button" data-finance-close>Cancelar</button><button class="primary">Registrar compra</button></footer></form></dialog>
